import React from "react";

export default function PollResults({ poll }) {
  if (!poll) return null;

  const total = poll.results?.reduce((a, b) => a + b, 0) || 0;

  return (
    <div className="results-shell">
      <div className="results-header-row">
        <span className="results-section-title">Question</span>
      </div>

      <div className="results-question-bar">
        <span className="results-question-text">{poll.question}</span>
      </div>

      <div className="results-options-list">
        {poll.options.map((opt, idx) => {
          const count = poll.results?.[idx] || 0;
          const pct = total ? Math.round((count / total) * 100) : 0;

          return (
            <div className="results-option-row" key={idx}>
              <div className="results-option-pill">
                {/* colored fill behind content */}
                <div
                  className="results-option-pill-fill"
                  style={{ width: `${pct || 2}%` }} // tiny min width so you can see something
                />
                <div className="results-option-pill-content">
                  <div className="results-option-main">
                    <div className="results-option-index">{idx + 1}</div>
                    <div className="results-option-name">{opt}</div>
                  </div>
                  <div className="results-option-pct">{pct}%</div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div className="results-footer">
        <span className="results-total">
          Total responses: <strong>{total}</strong>
        </span>
      </div>
    </div>
  );
}
